window.AUTH=window.AUTH||{};window.AUTH["19-1401"]={"d":"19-1401","id":"2021/19-1401","n":"Hughes v. Northwestern University","briefs":[{"k":"petitioner","label":"Brief of petitioners April Hughes, et al.","date":"2021-09-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-1401/191458/20210903232147432_Hughes%20opening%20brief%20--%20No.%2019-1401.pdf","side":"pet","n":41},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2021-09-10","url":"https://www.supremecourt.gov/DocketPDF/19/19-1401/192201/20210910175037653_19-1401tsacUnitedStates.pdf","side":"us","n":39},{"k":"respondent","label":"Brief of respondents Northwestern University, et al.","date":"2021-10-21","url":"https://www.supremecourt.gov/DocketPDF/19/19-1401/197166/20211021165210207_2021-10-21%20-%20Northwestern%20-%20Respondents%20Merits%20Brief%20with%20addendum.pdf","side":"res","n":55},{"k":"reply","label":"Reply of petitioners April Hughes, et al.","date":"2021-11-19","url":"https://www.supremecourt.gov/DocketPDF/19/19-1401/200682/20211119134224819_Hughes%20reply%20brief%20--%20No.%2019-1401.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/595us1r10_4hdj.pdf","tr":true,"items":[{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"op":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"29, 33, 35, 42","1":"25, 30, 33","2":"26, 27, 29, 40","3":"9"}},{"t":"case","label":"Beesley v. International Paper Co.","cite":"2014 WL 375432","y":2014,"court":"S.D. Ill. Jan. 31","by":{"0":"48"}},{"t":"case","label":"Bell Atlantic Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"op":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"0":"29, 45","1":"25, 30","2":"26, 29, 34, 40, 43"}},{"t":"case","label":"Braden v. Wal-Mart Stores, Inc.","cite":"588 F.3d 585","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/588/585/","by":{"0":"49","1":"20","2":"25, 36"}},{"t":"case","label":"Central States, Se. & Sw. Areas Pension Fund v. Central Transp., Inc.","cite":"472 U.S. 559","y":1985,"id":"1984/82-2157","sc":1,"sum":"Respondents must allow petitioners to conduct the requested audit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 19, 20","1":"2, 13, 14","3":"1, 5"}},{"t":"case","label":"Clark v. Duke Univ.","cite":"2019 WL 2588029","y":2019,"court":"M.D.N.C. June 24","by":{"0":"48","3":"24"}},{"t":"case","label":"Davis v. Washington Univ. in St. Louis","cite":"960 F.3d 478","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/478/","by":{"0":"31-32, 43","1":"20, 23","2":"7, 10, 27, 48"}},{"t":"case","label":"Erickson v. Pardus","cite":"551 U.S. 89","y":2007,"id":"2006/06-7317","sc":1,"sum":"The Court decided that a plaintiff can sufficiently allege that he suffered substantial harm by being denied medical treatment while incarcerated for the purpose of a claim under 42 U.S.C 1983.","sumSrc":"Oyez","by":{"0":"29","3":"9"}},{"t":"case","label":"Fifth Third Bancorp v. Dudenhoeffer","cite":"573 U.S. 409","y":2014,"id":"2013/12-751","sc":1,"op":1,"ar":1,"sum":"The Court held that a trustee of an employee stock ownership plan is subject to the same duty of prudence as the trustee of a Employee Retirement Income Security Act.","sumSrc":"Oyez","by":{"0":"4, 6, 42","1":"2, 13, 21","2":"passim","3":"1, 3, 5, 10, 11, 13"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Gordan v. Massachusetts Mut. Life Ins. Co.","cite":"2016 WL 11272044","y":2016,"court":"D. Mass. Nov. 3","by":{"0":"48"}},{"t":"case","label":"Harvard Coll. v. Amory","cite":"26 Mass. 446","y":1830,"url":"https://www.courtlistener.com/c/Mass./26/446/","by":{"0":"21"}},{"t":"case","label":"Kelly v. Johns Hopkins Univ.","cite":"2020 WL 434473","y":2020,"court":"D. Md. Jan. 28","sum":"Noting reduction in recordkeeping fees of $18 million from settlement.","sumSrc":"brief:3","by":{"0":"18, 48","3":"24"}},{"t":"case","label":"Kruger v. Novant Health, Inc.","cite":"2016 WL 6769066","y":2016,"court":"M.D.N.C. Sept. 29","by":{"0":"48"}},{"t":"case","label":"LaRue v. DeWolff, Boberg & Assocs., Inc.","cite":"552 U.S. 248","y":2008,"id":"2007/06-856","sc":1,"by":{"0":"47","2":"4, 6"}},{"t":"case","label":"Loomis v. Exelon Corp.","cite":"658 F.3d 667","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/658/667/","by":{"0":"14","2":"passim"}},{"t":"case","label":"Massachusetts v. Morash","cite":"490 U.S. 107","y":1989,"id":"1988/88-32","sc":1,"sum":"The Court concluded that an employee’s unused vacation time does not constitute an employee welfare benefit plan under the Employment Retirement Income Security Act of 1974.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Massachusetts Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4","1":"14"}},{"t":"case","label":"Matrixx Initiatives, Inc. v. Siracusano","cite":"563 U.S. 27","y":2011,"id":"2010/09-1156","sc":1,"sum":"The Court held that a plaintiff could state a claim based on a pharmaceutical company's non-disclosure of adverse event reports, even though the reports are not alleged to be statistically significant.","sumSrc":"Oyez","by":{"0":"16, 29, 42, 44","3":"9"}},{"t":"case","label":"Sacerdote v. New York Univ., --- F.4th ---","cite":"2021 WL 3610355","y":2021,"court":"2d Cir. Aug. 16","by":{"0":"31, 46","1":"19, 23, 24"}},{"t":"case","label":"Sweda v. University of Pennsylvania","cite":"923 F.3d 320","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/923/320/","sum":"Holding that allegations that fiduciary imprudently “retained expensive underperformers over better performing, cheaper alternatives” stated valid claim.","sumSrc":"brief:0","by":{"0":"32, 36, 37","1":"20, 23, 30","2":"47, 48, 49"}},{"t":"case","label":"Van Gorden v. Lunt","cite":"13 N.W.2d 341","y":1944,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/13/341/","by":{"0":"23"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"4, 20","1":"14","2":"22"}},{"t":"case","label":"Wall v. Boston Safe Deposit & Tr. Co.","cite":"150 N.E. 220","y":1926,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./150/220/","by":{"0":"15-16, 23, 33","2":"28, 29"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","subs":["(b)"],"stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"passim, 4, 18, 47","1":"1, 2, 13","3":"passim"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(34)","(13)","(21)(A)(i)","(3)","(35)"],"stext":{"head":"§1002. Definitions","paras":[[0,"For purposes of this subchapter:"],[0,"(1) The terms \"employee welfare benefit plan\" and \"welfare plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that such plan, fund, or program was established or is maintained for the purpose of providing for its participants or their beneficiaries, through the purchase of insurance or otherwise, (A) medical, surgical, or hospital care or benefits, or benefits in the event of sickness, accident, disability, death or unemployment, or vacation benefits, apprenticeship or other training programs, or day care centers, scholarship funds, or prepaid legal services, or (B) any benefit described in section 186(c) of this title (other than pensions on retirement or death, and insurance to provide such pensions)."],[0,"(2)(A) Except as provided in subparagraph (B), the terms \"employee pension benefit plan\" and \"pension plan\" mean any plan, fund, or program which was heretofore or is hereafter established or maintained by an employer or by an employee organization, or by both, to the extent that by its express terms or as a result of surrounding circumstances such plan, fund, or program—"],[1,"(i) provides retirement income to employees, or"],[1,"(ii) results in a deferral of income by employees for periods extending to the termination of covered employment or beyond,"],[0,"regardless of the method of calculating the contributions made to the plan, the method of calculating the benefits under the plan or the method of distributing benefits from the plan. A distribution from a plan, fund, or program shall not be treated as made in a form other than retirement income or as a distribution prior to termination of covered employment solely because such distribution is made to an employee who has attained age 62 and who is not separated from employment at the time of such distribution."],[0,"(B) The Secretary may by regulation prescribe rules consistent with the standards and purposes of this chapter providing one or more exempt categories under which—"],[1,"(i) severance pay arrangements, and"],[1,"(ii) supplemental retirement income payments, under which the pension benefits of retirees or their beneficiaries are supplemented to take into account some portion or all of the increases in the cost of living (as determined by the Secretary of Labor) since retirement,"],[0,"shall, for purposes of this subchapter, be treated as welfare plans rather than pension plans. In the case of any arrangement or payment a principal effect of which is the evasion of the standards or purposes of this chapter applicable to pension plans, such arrangement or payment shall be treated as a pension plan. An applicable voluntary early retirement incentive plan (as defined in section 457(e)(11)(D)(ii) of title 26) making payments or supplements described in section 457(e)(11)(D)(i) of title 26, and an applicable employment retention plan (as defined in section 457(f)(4)(C) of title 26) making payments of benefits described in section 457(f)(4)(A) of title 26, shall, for purposes of this subchapter, be treated as a welfare plan (and not a pension plan) with respect to such payments and supplements."],[0,"(C) A pooled employer plan shall be treated as—"],[1,"(i) a single employee pension benefit plan or single pension plan; and"],[1,"(ii) a plan to which section 1060(a) of this title applies."],[0,"(3) The term \"employee benefit plan\" or \"plan\" means an employee welfare benefit plan or an employee pension benefit plan or a plan which is both an employee welfare benefit plan and an employee pension benefit plan."],[0,"(4) The term \"employee organization\" means any labor union or any organization of any kind, or any agency or employee representation committee, association, group, or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning an employee benefit plan, or other matters incidental to employment relationships; or any employees' beneficiary association organized for the purpose in whole or in part, of establishing such a plan."],[0,"(5) The term \"employer\" means any person acting directly as an employer, or indirectly in the interest of an employer, in relation to an employee benefit plan; and includes a group or association of employers acting for an employer in such capacity."],[0,"(6) The term \"employee\" means any individual employed by an employer."],[0,"(7) The term \"participant\" means any employee or former employee of an employer, or any member or former member of an employee organization, who is or may become eligible to receive a benefit of any type from an employee benefit plan which covers employees of such employer or members of such organization, or whose beneficiaries may be eligible to receive any such benefit."],[0,"(8) The term \"beneficiary\" means a person designated by a participant, or by the terms of an employee benefit plan, who is or may become entitled to a benefit thereunder."],[0,"(9) The term \"person\" means an individual, partnership, joint venture, corporation, mutual company, joint-stock company, trust, estate, unincorporated organization, association, or employee organization."],[0,"(10) The term \"State\" includes any State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, and the Canal Zone. The term \"United States\" when used in the geographic sense means the States and the Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act (43 U.S.C. 1331–1343)."],[0,"(11) The term \"commerce\" means trade, traffic, commerce, transportation, or communication between any State and any place outside thereof."],[0,"(12) The term \"industry or activity affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and includes any activity or industry \"affecting commerce\" within the meaning of the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], or the Railway Labor Act [45 U.S.C. 151 et seq.]."],[0,"(13) The term \"Secretary\" means the Secretary of Labor."],[0,"(14) The term \"party in interest\" means, as to an employee benefit plan—"],[1,"(A) any fiduciary (including, but not limited to, any administrator, officer, trustee, or custodian), counsel, or employee of such employee benefit plan;"],[1,"(B) a person providing services to such plan;"],[1,"(C) an employer any of whose employees are covered by such plan;"],[1,"(D) an employee organization any of whose members are covered by such plan;"],[1,"(E) an owner, direct or indirect, of 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of a corporation.1"],[2,"(ii) the capital interest or the profits interest of a partnership, or"],[2,"(iii) the beneficial interest of a trust or unincorporated enterprise,"],[1,"which is an employer or an employee organization described in subparagraph (C) or (D);"],[1,"(F) a relative (as defined in paragraph (15)) of any individual described in subparagraph (A), (B), (C), or (E);"],[1,"(G) a corporation, partnership, or trust or estate of which (or in which) 50 percent or more of—"],[2,"(i) the combined voting power of all classes of stock entitled to vote or the total value of shares of all classes of stock of such corporation,"],[2,"(ii) the capital interest or profits interest of such partnership, or"],[2,"(iii) the beneficial interest of such trust or estate,"],[1,"is owned directly or indirectly, or held by persons described in subparagraph (A), (B), (C), (D), or (E);"],[1,"(H) an employee, officer, director (or an individual having powers or responsibilities similar to those of officers or directors), or a 10 percent or more shareholder directly or indirectly, of a person described in subparagraph (B), (C), (D), (E), or (G), or of the employee benefit plan; or"],[1,"(I) a 10 percent or more (directly or indirectly in capital or profits) partner or joint venturer of a person described in subparagraph (B), (C), (D), (E), or (G)."],[0,"The Secretary, after consultation and coordination with the Secretary of the Treasury, may by regulation prescribe a percentage lower than 50 percent for subparagraph (E) and (G) and lower than 10 percent for subparagraph (H) or (I). The Secretary may prescribe regulations for determining the ownership (direct or indirect) of profits and beneficial interests, and the manner in which indirect stockholdings are taken into account. Any person who is a party in interest with respect to a plan to which a trust described in section 501(c)(22) of title 26 is permitted to make payments under section 1403 of this title shall be treated as a party in interest with respect to such trust."],[0,"(15) The term \"relative\" means a spouse, ancestor, lineal descendant, or spouse of a lineal descendant."],[0,"(16)(A) The term \"administrator\" means—"],[1,"(i) the person specifically so designated by the terms of the instrument under which the plan is operated;"],[1,"(ii) if an administrator is not so designated, the plan sponsor; or"],[1,"(iii) in the case of a plan for which an administrator is not designated and a plan sponsor cannot be identified, such other person as the Secretary may by regulation prescribe."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1002?type=usc&year=mostrecent&link-type=html"},"head":"§1002. Definitions","tname":"Labor","by":{"0":"5","1":"1, 2, 3","2":"4","3":"2, 2, 2"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)(B)","(a)","(a)(1)(A)","(a)(1)(A)(ii)","(c)","(c)(1)(A)","(c)(1)(A)(ii)","(c)(5)(A)","(a)(1)","(a)(1)(C)"],"stext":{"head":"§1104. Fiduciary duties","paras":[[0,"(a) Prudent man standard of care"],[0,"(1) Subject to sections 1103(c) and (d), 1342, and 1344 of this title, a fiduciary shall discharge his duties with respect to a plan solely in the interest of the participants and beneficiaries and—"],[1,"(A) for the exclusive purpose of:"],[2,"(i) providing benefits to participants and their beneficiaries; and"],[2,"(ii) defraying reasonable expenses of administering the plan;"],[1,"(B) with the care, skill, prudence, and diligence under the circumstances then prevailing that a prudent man acting in a like capacity and familiar with such matters would use in the conduct of an enterprise of a like character and with like aims;"],[1,"(C) by diversifying the investments of the plan so as to minimize the risk of large losses, unless under the circumstances it is clearly prudent not to do so; and"],[1,"(D) in accordance with the documents and instruments governing the plan insofar as such documents and instruments are consistent with the provisions of this subchapter and subchapter III."],[0,"(2) In the case of an eligible individual account plan (as defined in section 1107(d)(3) of this title), the diversification requirement of paragraph (1)(C) and the prudence requirement (only to the extent that it requires diversification) of paragraph (1)(B) is not violated by acquisition or holding of qualifying employer real property or qualifying employer securities (as defined in section 1107(d)(4) and (5) of this title)."],[0,"(b) Indicia of ownership of assets outside jurisdiction of district courts"],[0,"Except as authorized by the Secretary by regulations, no fiduciary may maintain the indicia of ownership of any assets of a plan outside the jurisdiction of the district courts of the United States."],[0,"(c) Control over assets by participant or beneficiary"],[0,"(1)(A) In the case of a pension plan which provides for individual accounts and permits a participant or beneficiary to exercise control over the assets in his account, if a participant or beneficiary exercises control over the assets in his account (as determined under regulations of the Secretary)—"],[1,"(i) such participant or beneficiary shall not be deemed to be a fiduciary by reason of such exercise, and"],[1,"(ii) no person who is otherwise a fiduciary shall be liable under this part for any loss, or by reason of any breach, which results from such participant's or beneficiary's exercise of control, except that this clause shall not apply in connection with such participant or beneficiary for any blackout period during which the ability of such participant or beneficiary to direct the investment of the assets in his or her account is suspended by a plan sponsor or fiduciary."],[0,"(B) If a person referred to in subparagraph (A)(ii) meets the requirements of this subchapter in connection with authorizing and implementing the blackout period, any person who is otherwise a fiduciary shall not be liable under this subchapter for any loss occurring during such period."],[0,"(C) For purposes of this paragraph, the term \"blackout period\" has the meaning given such term by section 1021(i)(7) of this title."],[0,"(2) In the case of a simple retirement account established pursuant to a qualified salary reduction arrangement under section 408(p) of title 26, a participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account upon the earliest of—"],[1,"(A) an affirmative election among investment options with respect to the initial investment of any contribution,"],[1,"(B) a rollover to any other simple retirement account or individual retirement plan, or"],[1,"(C) one year after the simple retirement account is established."],[0,"No reports, other than those required under section 1021(g) of this title, shall be required with respect to a simple retirement account established pursuant to such a qualified salary reduction arrangement."],[0,"(3) In the case of a pension plan which makes a transfer to an individual retirement account or annuity of a designated trustee or issuer under section 401(a)(31)(B) of title 26, the participant or beneficiary shall, for purposes of paragraph (1), be treated as exercising control over the assets in the account or annuity upon—"],[1,"(A) the earlier of—"],[2,"(i) a rollover of all or a portion of the amount to another individual retirement account or annuity; or"],[2,"(ii) one year after the transfer is made; or"],[1,"(B) a transfer that is made in a manner consistent with guidance provided by the Secretary."],[0,"(4)(A) In any case in which a qualified change in investment options occurs in connection with an individual account plan, a participant or beneficiary shall not be treated for purposes of paragraph (1) as not exercising control over the assets in his account in connection with such change if the requirements of subparagraph (C) are met in connection with such change."],[0,"(B) For purposes of subparagraph (A), the term \"qualified change in investment options\" means, in connection with an individual account plan, a change in the investment options offered to the participant or beneficiary under the terms of the plan, under which—"],[1,"(i) the account of the participant or beneficiary is reallocated among one or more remaining or new investment options which are offered in lieu of one or more investment options offered immediately prior to the effective date of the change, and"],[1,"(ii) the stated characteristics of the remaining or new investment options provided under clause (i), including characteristics relating to risk and rate of return, are, as of immediately after the change, reasonably similar to those of the existing investment options as of immediately before the change."],[0,"(C) The requirements of this subparagraph are met in connection with a qualified change in investment options if—"],[1,"(i) at least 30 days and no more than 60 days prior to the effective date of the change, the plan administrator furnishes written notice of the change to the participants and beneficiaries, including information comparing the existing and new investment options and an explanation that, in the absence of affirmative investment instructions from the participant or beneficiary to the contrary, the account of the participant or beneficiary will be invested in the manner described in subparagraph (B),"],[1,"(ii) the participant or beneficiary has not provided to the plan administrator, in advance of the effective date of the change, affirmative investment instructions contrary to the change, and"],[1,"(iii) the investments under the plan of the participant or beneficiary as in effect immediately prior to the effective date of the change were the product of the exercise by such participant or beneficiary of control over the assets of the account within the meaning of paragraph (1)."],[0,"(5) Default investment arrangements.—"],[1,"(A) In general.—For purposes of paragraph (1), a participant or beneficiary in an individual account plan meeting the notice requirements of subparagraph (B) shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which, in the absence of an investment election by the participant or beneficiary, are invested by the plan in accordance with regulations prescribed by the Secretary. The regulations under this subparagraph shall provide guidance on the appropriateness of designating default investments that include a mix of asset classes consistent with capital preservation or long-term capital appreciation, or a blend of both."],[1,"(B) Notice requirements.—"],[2,"(i) In general.—The requirements of this subparagraph are met if each participant or beneficiary—"],[3,"(I) receives, within a reasonable period of time before each plan year, a notice explaining the employee's right under the plan to designate how contributions and earnings will be invested and explaining how, in the absence of any investment election by the participant or beneficiary, such contributions and earnings will be invested, and"],[3,"(II) has a reasonable period of time after receipt of such notice and before the beginning of the plan year to make such designation."],[2,"(ii) Form of notice.—The requirements of clauses (i) and (ii) of section 401(k)(12)(D) of title 26 shall apply with respect to the notices described in this subparagraph."],[0,"(6) Default investment arrangements for a pension-linked emergency savings account.—For purposes of paragraph (1), a participant in a pension-linked emergency savings account shall be treated as exercising control over the assets in the account with respect to the amount of contributions and earnings which are invested in accordance with section 1193(c)(1)(A)(iii) of this title."],[0,"(d) Plan terminations"],[0,"(1) If, in connection with the termination of a pension plan which is a single-employer plan, there is an election to establish or maintain a qualified replacement plan, or to increase benefits, as provided under section 4980(d) of title 26, a fiduciary shall discharge the fiduciary's duties under this subchapter and subchapter III in accordance with the following requirements:"],[1,"(A) In the case of a fiduciary of the terminated plan, any requirement—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1104?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1104. Fiduciary duties","tname":"Labor","by":{"0":"2, 4, 15, 19, 20, 34, 45","1":"2, 2, 13, 3, 16, 24, 29, 2, 3, 8, 13, 29, 24","2":"5, 5, 19, 28, 32, 34, 5, 20, 5, 20, 5, 36","3":"2, 9, 11, 20, 3, 4, 5, 4"}},{"t":"usc","label":"29 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/29/1106","subs":["(a)(1)"],"stext":{"head":"§1106. Prohibited transactions","paras":[[0,"(a) Transactions between plan and party in interest"],[0,"Except as provided in section 1108 of this title:"],[1,"(1) A fiduciary with respect to a plan shall not cause the plan to engage in a transaction, if he knows or should know that such transaction constitutes a direct or indirect—"],[2,"(A) sale or exchange, or leasing, of any property between the plan and a party in interest;"],[2,"(B) lending of money or other extension of credit between the plan and a party in interest;"],[2,"(C) furnishing of goods, services, or facilities between the plan and a party in interest;"],[2,"(D) transfer to, or use by or for the benefit of a party in interest, of any assets of the plan; or"],[2,"(E) acquisition, on behalf of the plan, of any employer security or employer real property in violation of section 1107(a) of this title."],[1,"(2) No fiduciary who has authority or discretion to control or manage the assets of a plan shall permit the plan to hold any employer security or employer real property if he knows or should know that holding such security or real property violates section 1107(a) of this title."],[0,"(b) Transactions between plan and fiduciary"],[0,"A fiduciary with respect to a plan shall not—"],[1,"(1) deal with the assets of the plan in his own interest or for his own account,"],[1,"(2) in his individual or in any other capacity act in any transaction involving the plan on behalf of a party (or represent a party) whose interests are adverse to the interests of the plan or the interests of its participants or beneficiaries, or"],[1,"(3) receive any consideration for his own personal account from any party dealing with such plan in connection with a transaction involving the assets of the plan."],[0,"(c) Transfer of real or personal property to plan by party in interest"],[0,"A transfer of real or personal property by a party in interest to a plan shall be treated as a sale or exchange if the property is subject to a mortgage or similar lien which the plan assumes or if it is subject to a mortgage or similar lien which a party-in-interest placed on the property within the 10-year period ending on the date of the transfer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1106?type=usc&year=mostrecent&link-type=html"},"head":"§1106. Prohibited transactions","tname":"Labor","by":{"0":"12","1":"32, 5"}},{"t":"usc","label":"29 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/29/1109","subs":["(a)"],"stext":{"head":"§1109. Liability for breach of fiduciary duty","paras":[[0,"(a) Any person who is a fiduciary with respect to a plan who breaches any of the responsibilities, obligations, or duties imposed upon fiduciaries by this subchapter shall be personally liable to make good to such plan any losses to the plan resulting from each such breach, and to restore to such plan any profits of such fiduciary which have been made through use of assets of the plan by the fiduciary, and shall be subject to such other equitable or remedial relief as the court may deem appropriate, including removal of such fiduciary. A fiduciary may also be removed for a violation of section 1111 of this title."],[0,"(b) No fiduciary shall be liable with respect to a breach of fiduciary duty under this subchapter if such breach was committed before he became a fiduciary or after he ceased to be a fiduciary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1109?type=usc&year=mostrecent&link-type=html"},"head":"§1109. Liability for breach of fiduciary duty","tname":"Labor","by":{"0":"5","1":"2, 13","2":"5"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(2)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"5, 11","1":"1, 2, 13","2":"5"}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(k)"],"stext":{"head":"§401. Qualified pension, profit-sharing, and stock bonus plans","paras":[[0,"(a) Requirements for qualification"],[0,"A trust created or organized in the United States and forming part of a stock bonus, pension, or profit-sharing plan of an employer for the exclusive benefit of his employees or their beneficiaries shall constitute a qualified trust under this section—"],[1,"(1) if contributions are made to the trust by such employer, or employees, or both, or by another employer who is entitled to deduct his contributions under section 404(a)(3)(B) (relating to deduction for contributions to profit-sharing and stock bonus plans), or by a charitable remainder trust pursuant to a qualified gratuitous transfer (as defined in section 664(g)(1)), for the purpose of distributing to such employees or their beneficiaries the corpus and income of the fund accumulated by the trust in accordance with such plan;"],[1,"(2) if under the trust instrument it is impossible, at any time prior to the satisfaction of all liabilities with respect to employees and their beneficiaries under the trust, for any part of the corpus or income to be (within the taxable year or thereafter) used for, or diverted to, purposes other than for the exclusive benefit of his employees or their beneficiaries (but this paragraph shall not be construed, in the case of a multiemployer plan, to prohibit the return of a contribution within 6 months after the plan administrator determines that the contribution was made by a mistake of fact or law (other than a mistake relating to whether the plan is described in section 401(a) or the trust which is part of such plan is exempt from taxation under section 501(a), or the return of any withdrawal liability payment determined to be an overpayment within 6 months of such determination));"],[1,"(3) if the plan of which such trust is a part satisfies the requirements of section 410 (relating to minimum participation standards); and"],[1,"(4) if the contributions or benefits provided under the plan do not discriminate in favor of highly compensated employees (within the meaning of section 414(q)). For purposes of this paragraph, there shall be excluded from consideration employees described in section 410(b)(3)(A) and (C)."],[1,"(5) Special rules relating to nondiscrimination requirements.—"],[2,"(A) Salaried or clerical employees.—A classification shall not be considered discriminatory within the meaning of paragraph (4) or section 410(b)(2)(A)(i) merely because it is limited to salaried or clerical employees."],[2,"(B) Contributions and benefits may bear uniform relationship to compensation.—A plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the contributions or benefits of, or on behalf of, the employees under the plan bear a uniform relationship to the compensation (within the meaning of section 414(s)) of such employees."],[2,"(C) Certain disparity permitted.—A plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the contributions or benefits of, or on behalf of, the employees under the plan favor highly compensated employees (as defined in section 414(q)) in the manner permitted under subsection (l)."],[2,"(D) Integrated defined benefit plan.—"],[3,"(i) In general.—A defined benefit plan shall not be considered discriminatory within the meaning of paragraph (4) merely because the plan provides that the employer-derived accrued retirement benefit for any participant under the plan may not exceed the excess (if any) of—"],[4,"(I) the participant's final pay with the employer, over"],[4,"(II) the employer-derived retirement benefit created under Federal law attributable to service by the participant with the employer."],[0,"For purposes of this clause, the employer-derived retirement benefit created under Federal law shall be treated as accruing ratably over 35 years."],[3,"(ii) Final pay.—For purposes of this subparagraph, the participant's final pay is the compensation (as defined in section 414(q)(4)) paid to the participant by the employer for any year—"],[4,"(I) which ends during the 5-year period ending with the year in which the participant separated from service for the employer, and"],[4,"(II) for which the participant's total compensation from the employer was highest."],[2,"(E) 2 or more plans treated as single plan.—For purposes of determining whether 2 or more plans of an employer satisfy the requirements of paragraph (4) when considered as a single plan—"],[3,"(i) Contributions.—If the amount of contributions on behalf of the employees allowed as a deduction under section 404 for the taxable year with respect to such plans, taken together, bears a uniform relationship to the compensation (within the meaning of section 414(s)) of such employees, the plans shall not be considered discriminatory merely because the rights of employees to, or derived from, the employer contributions under the separate plans do not become nonforfeitable at the same rate."],[3,"(ii) Benefits.—If the employees' rights to benefits under the separate plans do not become nonforfeitable at the same rate, but the levels of benefits provided by the separate plans satisfy the requirements of regulations prescribed by the Secretary to take account of the differences in such rates, the plans shall not be considered discriminatory merely because of the difference in such rates."],[2,"(F) Social security retirement age.—For purposes of testing for discrimination under paragraph (4)—"],[3,"(i) the social security retirement age (as defined in section 415(b)(8)) shall be treated as a uniform retirement age, and"],[3,"(ii) subsidized early retirement benefits and joint and survivor annuities shall not be treated as being unavailable to employees on the same terms merely because such benefits or annuities are based in whole or in part on an employee's social security retirement age (as so defined)."],[2,"(G) Governmental plans.—Paragraphs (3) and (4) shall not apply to a governmental plan (within the meaning of section 414(d))."],[1,"(6) A plan shall be considered as meeting the requirements of paragraph (3) during the whole of any taxable year of the plan if on one day in each quarter it satisfied such requirements."],[1,"(7) A trust shall not constitute a qualified trust under this section unless the plan of which such trust is a part satisfies the requirements of section 411 (relating to minimum vesting standards)."],[1,"(8) A trust forming part of a defined benefit plan shall not constitute a qualified trust under this section unless the plan provides that forfeitures must not be applied to increase the benefits any employee would otherwise receive under the plan."],[1,"(9) Required distributions.—"],[2,"(A) In general.—A trust shall not constitute a qualified trust under this subsection unless the plan provides that the entire interest of each employee—"],[3,"(i) will be distributed to such employee not later than the required beginning date, or"],[3,"(ii) will be distributed, beginning not later than the required beginning date, in accordance with regulations, over the life of such employee or over the lives of such employee and a designated beneficiary (or over a period not extending beyond the life expectancy of such employee or the life expectancy of such employee and a designated beneficiary)."],[2,"(B) Required distribution where employee dies before entire interest is distributed.—"],[3,"(i) Where distributions have begun under subparagraph (A)(ii).—A trust shall not constitute a qualified trust under this section unless the plan provides that if—"],[4,"(I) the distribution of the employee's interest has begun in accordance with subparagraph (A)(ii), and"],[4,"(II) the employee dies before his entire interest has been distributed to him,"],[0,"the remaining portion of such interest will be distributed at least as rapidly as under the method of distributions being used under subparagraph (A)(ii) as of the date of his death."],[3,"(ii) 5-year rule for other cases.—A trust shall not constitute a qualified trust under this section unless the plan provides that, if an employee dies before the distribution of the employee's interest has begun in accordance with subparagraph (A)(ii), the entire interest of the employee will be distributed within 5 years after the death of such employee."],[3,"(iii) Exception to 5-year rule for certain amounts payable over life of beneficiary.—If—"],[4,"(I) any portion of the employee's interest is payable to (or for the benefit of) a designated beneficiary,"],[4,"(II) such portion will be distributed (in accordance with regulations) over the life of such designated beneficiary (or over a period not extending beyond the life expectancy of such beneficiary), and"],[4,"(III) such distributions begin not later than 1 year after the date of the employee's death or such later date as the Secretary may by regulations prescribe,"],[0,"for purposes of clause (ii), the portion referred to in subclause (I) shall be treated as distributed on the date on which such distributions begin."],[3,"(iv) Special rule for surviving spouse of employee.—If the designated beneficiary referred to in clause (iii)(I) is the surviving spouse of the employee and the surviving spouse elects the treatment in this clause—"],[4,"(I) the regulations referred to in clause (iii)(II) shall treat the surviving spouse as if the surviving spouse were the employee,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/401?type=usc&year=mostrecent&link-type=html"},"head":"§401. Qualified pension, profit-sharing, and stock bonus plans","tname":"Internal Revenue Code","by":{"0":"5","2":"6"}},{"t":"usc","label":"26 U.S.C. § 403","url":"https://www.law.cornell.edu/uscode/text/26/403","subs":["(a)(1)","(b)","(b)(7)"],"stext":{"head":"§403. Taxation of employee annuities","paras":[[0,"(a) Taxability of beneficiary under a qualified annuity plan"],[0,"(1) Distributee taxable under section 72"],[1,"If an annuity contract is purchased by an employer for an employee under a plan which meets the requirements of section 404(a)(2) (whether or not the employer deducts the amounts paid for the contract under such section), the amount actually distributed to any distributee under the contract shall be taxable to the distributee (in the year in which so distributed) under section 72 (relating to annuities)."],[0,"(2) Special rule for health and long-term care insurance"],[1,"To the extent provided in section 402(l), paragraph (1) shall not apply to the amount distributed under the contract which is otherwise includible in gross income under this subsection."],[0,"(3) Self-employed individuals"],[1,"For purposes of this subsection, the term \"employee\" includes an individual who is an employee within the meaning of section 401(c)(1), and the employer of such individual is the person treated as his employer under section 401(c)(4)."],[0,"(4) Rollover amounts"],[0,"(A) General rule"],[2,"If—"],[3,"(i) any portion of the balance to the credit of an employee in an employee annuity described in paragraph (1) is paid to him in an eligible rollover distribution (within the meaning of section 402(c)(4)),"],[3,"(ii) the employee transfers any portion of the property he receives in such distribution to an eligible retirement plan, and"],[3,"(iii) in the case of a distribution of property other than money, the amount so transferred consists of the property distributed,"],[2,"then such distribution (to the extent so transferred) shall not be includible in gross income for the taxable year in which paid."],[0,"(B) Certain rules made applicable"],[2,"The rules of paragraphs (2) through (7) and (11) and (9) of section 402(c) and section 402(f) shall apply for purposes of subparagraph (A)."],[0,"(5) Direct trustee-to-trustee transfer"],[1,"Any amount transferred in a direct trustee-to-trustee transfer in accordance with section 401(a)(31) shall not be includible in gross income for the taxable year of such transfer."],[0,"(b) Taxability of beneficiary under annuity purchased by section 501(c)(3) organization or public school"],[0,"(1) General rule"],[1,"If—"],[2,"(A) an annuity contract is purchased—"],[3,"(i) for an employee by an employer described in section 501(c)(3) which is exempt from tax under section 501(a),"],[3,"(ii) for an employee (other than an employee described in clause (i)), who performs services for an educational organization described in section 170(b)(1) (A)(ii), by an employer which is a State, a political subdivision of a State, or an agency or instrumentality of any one or more of the foregoing, or"],[3,"(iii) for the minister described in section 414(e)(5)(A) by the minister or by an employer,"],[2,"(B) such annuity contract is not subject to subsection (a),"],[2,"(C) the employee's rights under the contract are nonforfeitable, except for failure to pay future premiums,"],[2,"(D) except in the case of a contract purchased by a church, such contract is purchased under a plan which meets the nondiscrimination requirements of paragraph (12), and"],[2,"(E) in the case of a contract purchased under a salary reduction agreement, the contract meets the requirements of section 401(a)(30),"],[1,"then contributions and other additions by such employer for such annuity contract shall be excluded from the gross income of the employee for the taxable year to the extent that the aggregate of such contributions and additions (when expressed as an annual addition (within the meaning of section 415(c)(2))) does not exceed the applicable limit under section 415. The amount actually distributed to any distributee under such contract shall be taxable to the distributee (in the year in which so distributed) under section 72 (relating to annuities). For purposes of applying the rules of this subsection to contributions and other additions by an employer for a taxable year, amounts transferred to a contract described in this paragraph by reason of a rollover contribution described in paragraph (8) of this subsection or section 408(d)(3)(A)(ii) shall not be considered contributed by such employer."],[0,"(2) Special rule for health and long-term care insurance"],[1,"To the extent provided in section 402(l), paragraph (1) shall not apply to the amount distributed under the contract which is otherwise includible in gross income under this subsection."],[0,"(3) Includible compensation"],[1,"For purposes of this subsection, the term \"includible compensation\" means, in the case of any employee, the amount of compensation which is received from the employer described in paragraph (1)(A), and which is includible in gross income (computed without regard to section 911) for the most recent period (ending not later than the close of the taxable year) which under paragraph (4) may be counted as one year of service, and which precedes the taxable year by no more than five years. Such term does not include any amount contributed by the employer for any annuity contract to which this subsection applies. Such term includes—"],[2,"(A) any elective deferral (as defined in section 402(g)(3)), and"],[2,"(B) any amount which is contributed or deferred by the employer at the election of the employee and which is not includible in the gross income of the employee by reason of section 125, 132(f)(4), or 457."],[0,"(4) Years of service"],[1,"In determining the number of years of service for purposes of this subsection, there shall be included—"],[2,"(A) one year for each full year during which the individual was a full-time employee of the organization purchasing the annuity for him, and"],[2,"(B) a fraction of a year (determined in accordance with regulations prescribed by the Secretary) for each full year during which such individual was a part-time employee of such organization and for each part of a year during which such individual was a full-time or part-time employee of such organization."],[1,"In no case shall the number of years of service be less than one."],[0,"(5) Application to more than one annuity contract"],[1,"If for any taxable year of the employee this subsection applies to 2 or more annuity contracts purchased by the employer, such contracts shall be treated as one contract."],[0,"[(6) Repealed. Pub. L. 107–147, title IV, §411(p)(2), Mar. 9, 2002, 116 Stat. 50]"],[0,"(7) Custodial accounts"],[0,"(A) Amounts paid treated as contributions"],[2,"For purposes of this title, amounts paid by an employer described in paragraph (1)(A) to a custodial account which satisfies the requirements of section 401(f)(2) shall be treated as amounts contributed by him for an annuity contract for his employee if the amounts are to be held in that custodial account and are invested in regulated investment company stock or a group trust intended to satisfy the requirements of Internal Revenue Service Revenue Ruling 81–100 (or any successor guidance), and under the custodial account—"],[3,"(i) no such amounts may be paid or made available to any distributee (unless such amount is a distribution to which section 72(t)(2)(G) applies) before—"],[4,"(I) the employee dies,"],[4,"(II) the employee attains age 59½,"],[4,"(III) the employee has a severance from employment,"],[4,"(IV) the employee becomes disabled (within the meaning of section 72(m)(7)),"],[4,"(V) subject to the provisions of paragraph (17), the employee encounters financial hardship, or"],[4,"(VI) except as may be otherwise provided by regulations, with respect to amounts invested in a lifetime income investment (as defined in section 401(a)(38)(B)(ii)), the date that is 90 days prior to the date that such lifetime income investment may no longer be held as an investment option under the contract, and"],[3,"(ii) in the case of amounts described in clause (i)(VI), such amounts will be distributed only in the form of a qualified distribution (as defined in section 401(a)(38)(B)(i)) or a qualified plan distribution annuity contract (as defined in section 401(a)(38)(B)(iv))."],[0,"(B) Account treated as plan"],[2,"For purposes of this title, a custodial account which satisfies the requirements of section 401(f)(2) shall be treated as an organization described in section 401(a) solely for purposes of subchapter F and subtitle F with respect to amounts received by it (and income from investment thereof)."],[0,"(C) Regulated investment company"],[2,"For purposes of this paragraph, the term \"regulated investment company\" means a domestic corporation which is a regulated investment company within the meaning of section 851(a)."],[0,"(D) Employee certification"],[2,"In determining whether a distribution is upon the financial hardship of an employee, the administrator of the plan may rely on a written certification by the employee that the distribution is—"],[3,"(i) on account of a financial need of a type which is deemed in regulations prescribed by the Secretary to be an immediate and heavy financial need, and"],[3,"(ii) not in excess of the amount required to satisfy such financial need, and"],[2,"that the employee has no alternative means reasonably available to satisfy such financial need. The Secretary may provide by regulations for exceptions to the rule of the preceding sentence in cases where the plan administrator has actual knowledge to the contrary of the employee's certification, and for procedures for addressing cases of employee misrepresentation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/403?type=usc&year=mostrecent&link-type=html"},"head":"§403. Taxation of employee annuities","tname":"Internal Revenue Code","by":{"0":"6, 5, 6","1":"2, 28","2":"6"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"reg","label":"29 C.F.R. § 2510.3-2","url":"https://www.ecfr.gov/current/title-29/section-2510.3-2","by":{"0":"5"}},{"t":"reg","label":"29 C.F.R. § 2550.404a-1","url":"https://www.ecfr.gov/current/title-29/section-2550.404a-1","subs":["(b)(1)(i)"],"by":{"0":"37"}},{"t":"rule","label":"Fed. R. Civ. P. 8","url":"https://www.law.cornell.edu/rules/frcp/rule_8","subs":["(a)(2)"],"by":{"0":"34"}},{"t":"case","label":"Brief for the United States as Amicus Curiae Supporting Pet’rs, Tibble v. Edison Int’l","cite":"2014 WL 6984131","y":2014,"court":"U.S. Dec. 9","by":{"0":"25"}},{"t":"case","label":"Dura Pharms., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"sum":"The Court held that an inflated purchase price did not by itself prove \"loss causation.\" At most, an inflated purchase price suggested that misrepresentation \"touched upon\" a later economic loss, but did not necessarily cause it.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Howell v. Motorola, Inc.","cite":"633 F.3d 552","y":2011,"url":"https://www.courtlistener.com/c/F.3d/633/552/","by":{"1":"23, 24","3":"4, 5"}},{"t":"case","label":"Jones v. Harris Assocs. L. P.","cite":"559 U.S. 335","y":2010,"id":"2009/08-586","sc":1,"sum":"The Court held that Section 36(b) of the Investment Company Act requires a determination that the financial adviser charges a fee that is \"so disproportionately large is bears no reasonable relationship to the services rendered\" before legal action may be taken.","sumSrc":"Oyez","by":{"1":"30, 31","2":"50"}},{"t":"case","label":"Pension Benefit Guar. Corp. ex rel. St. Vincent Catholic Med. Ctrs. Ret. Plan v. Morgan Stanley Inv. Mgmt. Inc.","cite":"712 F.3d 705","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/712/705/","by":{"1":"19"}},{"t":"case","label":"Pfeil v. State St. Bank & Trust Co.","cite":"671 F.3d 585","y":2012,"url":"https://www.courtlistener.com/c/F.3d/671/585/","by":{"1":"23","3":"3, 4, 5"}},{"t":"case","label":"Tussey v. ABB, Inc.","cite":"746 F.3d 327","y":2014,"url":"https://www.courtlistener.com/c/F.3d/746/327/","by":{"1":"30"}},{"t":"case","label":"Young v. General Motors Inv. Mgmt. Corp.","cite":"325 Fed. Appx. 31","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./325/31/","by":{"1":"30"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)(1)"],"by":{"1":"2"}},{"t":"usc","label":"29 U.S.C. § 1108","url":"https://www.law.cornell.edu/uscode/text/29/1108","by":{"1":"32"}},{"t":"usc","label":"29 U.S.C. § 1135","url":"https://www.law.cornell.edu/uscode/text/29/1135","by":{"1":"24"}},{"t":"usc","label":"15 U.S.C. § 80a-1","url":"https://www.law.cornell.edu/uscode/text/15/80a-1","by":{"1":"30"}},{"t":"usc","label":"15 U.S.C. § 80a-35","url":"https://www.law.cornell.edu/uscode/text/15/80a-35","subs":["(b)"],"by":{"1":"30"}},{"t":"reg","label":"Reasonable Contract or Arrangement Under Section 408(b)(2)—Fee Disclosure, 77 Fed. Reg. 5632","url":"https://www.govinfo.gov/link/fr/77/5632","by":{"1":"32"}},{"t":"case","label":"Amgen Inc. v. Harris","cite":"577 U.S. 308","y":2016,"id":"2015/15-278","sc":1,"sum":"The Court held that the court of appeals erred in failing to assess whether the complaint “plausibly alleged” a breach of the duty of prudence under the standard the Court established in Fifth Third v. Dudenhoeffer.","sumSrc":"Oyez","by":{"2":"27, 31, 45","3":"10"}},{"t":"case","label":"Caterino v. Barry","cite":"8 F.3d 878","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/8/878/","by":{"2":"19"}},{"t":"case","label":"Central Virginia Community College v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Chao v. Merino","cite":"452 F.3d 174","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/452/174/","by":{"2":"32"}},{"t":"case","label":"Conkright v. Frommert","cite":"559 U.S. 506","y":2010,"id":"2009/08-810","sc":1,"sum":"The Court held that the Second Circuit Court of Appeals erred when they did not hold a claim of unfair pension distribution by employees of the Xerox Corporation to a deferential standard of review.","sumSrc":"Oyez","by":{"2":"3, 4, 48, 49"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Fink v. National Savings & Trust Co.","cite":"772 F.2d 951","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/772/951/","by":{"2":"30","3":"11"}},{"t":"case","label":"Green v. Crapo","cite":"62 N.E. 956","y":1902,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./62/956/","by":{"2":"41"}},{"t":"case","label":"Hagedorn v. Arens","cite":"150 A. 4","y":1930,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/A./150/4/","by":{"2":"31"}},{"t":"case","label":"Hecker v. Deere & Co.","cite":"556 F.3d 575","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/575/","by":{"2":"20, 21, 25, 40"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"sum":"The Court held Hughes did not violate the ERISA by establishing an early retirement program and creating a noncontributory benefit structure for new participants. Justice Thomas, writing for the Court, said the plan amendments \"did not affect the rights of pre-existing plan participants and Hughes did not use the surplus for its own benefit.\".","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Langbecker v. Electronic Data Systems Corp.","cite":"476 F.3d 299","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/476/299/","by":{"2":"20, 21","3":"5"}},{"t":"case","label":"Lawrence v. Florida","cite":"549 U.S. 327","y":2007,"id":"2006/05-8820","sc":1,"sum":"The Court ruled 5-4 that the time a habeas petition is pending before the Supreme Court counts toward the one-year statute of limitations in the Antiterrorism and Effective Death Penalty Act. Section 2244(d)(2) of the Act stops the clock on the time limit while the prisoner appeals in state courts, but the Court ruled that appeals to the Supreme Court are not part of the process referred to in the Act.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Lockheed Corp. v. Spink","cite":"517 U.S. 882","y":1996,"id":"1995/95-809","sc":1,"sum":"In unanimous and 7-2 decisions, announced by Justice Clarence Thomas, the Court ruled that businesses may condition early retirement benefits on the forfeiture of the right to sue in a job-related claim. The Court also ruled that the government could not retroactively apply retirement income benefit laws.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"NationsBank of North Carolina, N.A. v. Variable Annuity Life Insurance Co.","cite":"513 U.S. 251","y":1995,"id":"1994/93-1612","sc":1,"sum":"Petitioner national bank and its brokerage subsidiary applied to the Comptroller of the Currency, charged by Congress with superintendence of national banks, to allow the subsidiary to act as an agent in the sale of annuities. Under the proposed plan, bank customers could purchase a \"variable annuity\"-which invests payments in a designated way and yields income that varies with investment performance-a \"fixed\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"North Carolina Department of Revenue v. Kimberley Rice Kaestner 1992 Family Trust","cite":"139 S. Ct. 2213","y":2019,"id":"2018/18-457","sc":1,"sum":"The presence of in-state beneficiaries alone does not empower a State to tax trust income that has not been distributed to the beneficiaries where the beneficiaries have no right to demand that income and are uncertain to receive it.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22"}},{"t":"case","label":"Renfro v. Unisys Corp.","cite":"671 F.3d 314","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/671/314/","by":{"2":"6, 19, 20"}},{"t":"case","label":"Sacerdote v. New York Universiy","cite":"9 F.4th 95","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/9/95/","by":{"2":"42"}},{"t":"case","label":"Tellabs, Inc. v. Makor Issues & Rights, Ltd.","cite":"551 U.S. 308","y":2007,"id":"2006/06-484","sc":1,"sum":"The Court ruled by a vote of 8-1 that a securities fraud complaint must allege facts establishing an inference of guilty intent that is \"cogent and at least as compelling as any opposing inference of nonfraudulent intent.\" Justice Ruth Bader Ginsburg wrote that opinion for the Court, which held that the Seventh Circuit's more relaxed standard was not strong enough to comport with Congress's intent in PSLRA to limit securities fraud litigation. \"The strength of an inference cannot be decided in a vacuum.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Thole v. U.S. Bank N.A.","cite":"140 S. Ct. 1615","y":2020,"id":"2019/17-1712","sc":1,"sum":"The Court held that an ERISA plan participant lacks judicial standing to seek injunctive relief or restoration of plan losses caused by fiduciary breach if he cannot demonstrate individual financial loss or the imminent risk thereof.","sumSrc":"Oyez","by":{"2":"4, 22, 35","3":"7"}},{"t":"case","label":"Tibble v. Edison International","cite":"575 U.S. 523","y":2015,"id":"2014/13-550","sc":1,"op":3,"sum":"The Court held that, according to trust law, the fiduciary duty includes a continuing duty to monitor investments, and that a breach of that duty within six years of the filing of a lawsuit under the Employee Retirement Income Security Act is sufficient to allow the case to proceed.","sumSrc":"Oyez","by":{"2":"20, 22, 23, 24"}},{"t":"case","label":"Wilcox v. Georgetown University","cite":"2019 WL 132281","y":2019,"court":"D.D.C. Jan. 8","by":{"2":"29"}},{"t":"usc","label":"29 U.S.C. § 1113","url":"https://www.law.cornell.edu/uscode/text/29/1113","by":{"2":"23"}},{"t":"reg","label":"29 C.F.R. § 2550.404a-5","url":"https://www.ecfr.gov/current/title-29/section-2550.404a-5","subs":["(c)(2)","(c)(3)","(h)(5)(ii)"],"by":{"2":"6, 8, 8, 8"}},{"t":"reg","label":"29 C.F.R. § 2550.404c-1","url":"https://www.ecfr.gov/current/title-29/section-2550.404c-1","subs":["(b)(2)","(b)(2)(ii)","(b)(3)(i)","(d)(2)(iv)"],"by":{"2":"6, 7, 6, 20, 36, 6, 21","3":"4"}},{"t":"reg","label":"OTHER AUTHORITIES, 72 Fed. Reg. 41,128","url":"https://www.govinfo.gov/link/fr/72/41128","by":{"2":"10"}},{"t":"reg","label":"75 Fed. Reg. 64,910","url":"https://www.govinfo.gov/link/fr/75/64910","by":{"2":"8","3":"4"}},{"t":"case","label":"Allen v. Wells Fargo & Co.","cite":"967 F.3d 767","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/967/767/","by":{"3":"10"}},{"t":"case","label":"Cates v. Trustees of Columbia Univ.","cite":"2021 WL 4847890","y":2021,"court":"S.D.N.Y. Oct. 18","by":{"3":"24"}},{"t":"case","label":"DiFelice v. U.S. Airways, Inc.","cite":"497 F.3d 410","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/497/410/","by":{"3":"3, 4, 5"}},{"t":"case","label":"Hecker v. Deere & Co.: 556 F.3d 575 (7th Cir. 2009), on denial of reh’g","cite":"569 F.3d 708","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/569/708/","by":{"3":"4"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"op":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Tatum v. RJR Pension Inv. Comm.","cite":"855 F.3d 553","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/553/","by":{"3":"11"}},{"t":"case","label":"Tibble v. Edison Int’l: 2010 WL 2757153 (C.D. Cal. July 8, 2010), aff ’d","cite":"729 F.3d 1110","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/1110/","by":{"3":"17, 18"}},{"t":"case","label":"OTHER MATERIALS Brief of the Amicus Curiae, Thomas E. Perez, Secretary of Labor, U.S. Dep’t of Labor, in Support of Appellant, Tatum v. RJR Pension Inv. Comm.","cite":"2016 WL 4751078","by":{"3":"11"}},{"t":"case","label":"Brief for the Secretary of Labor as Amicus Curiae in Support of Plaintiffs-Appellants, Tibble v. Edison Int’l","cite":"2011 WL 2178417","by":{"3":"4"}}]};